function hasCycle(head) {
  let slow = head, fast = head;
  while (fast !== null && fast.next !== null && fast.next.next !== null) {
    slow = slow.next;             // +1
    fast = fast.next.next.next;   // +3  <-- teammate's change
    if (slow === fast) return true;
  }
  return false;
}
